// Generate tests/fixtures/bootstrap.sexp from QuantLib's PiecewiseYieldCurve.
//
//   nix develop .#fixtures -c sh tests/fixtures/generate.sh
//
// Valued on 2026-09-24. Six curves: USD SOFR (OIS 1W-30Y), EUR ESTR (OIS
// 1W-30Y), and EURIBOR 6M (a deposit, FRAs, swaps 2Y-30Y) discounted on the
// ESTR curve, each bootstrapped with Discount/LogLinear and with
// ForwardRate/ConvexMonotone. Each curve is a plist: :name, :interpolation,
// :discount-curve (the name of the curve it discounts on, or nil), :helpers,
// each (kind tenor-or-months quote pillar implied), and :discounts, the
// curve's discount factors at 50 dates, each ("date" value).

#include <ql/quantlib.hpp>
#include <ql/version.hpp>

#include <cstdio>
#include <string>
#include <vector>

using namespace QuantLib;

namespace {

std::string iso(const Date& d) {
    char buffer[16];
    std::snprintf(buffer, sizeof buffer, "%04d-%02d-%02d", d.year(), int(d.month()),
                  d.dayOfMonth());
    return buffer;
}

struct Quoted { std::string kind, tenor; double quote; };

const Date today(24, September, 2026);

Period parsePeriod(const std::string& s) {
    int n = std::stoi(s.substr(0, s.size() - 1));
    switch (s.back()) {
      case 'D': return Period(n, Days);
      case 'W': return Period(n, Weeks);
      case 'M': return Period(n, Months);
      default: return Period(n, Years);
    }
}

std::vector<ext::shared_ptr<RateHelper> > helpers(const std::vector<Quoted>& quotes,
                                                  const ext::shared_ptr<OvernightIndex>& on,
                                                  int paymentLag,
                                                  const Handle<YieldTermStructure>& discount) {
    std::vector<ext::shared_ptr<RateHelper> > result;
    auto euribor = ext::make_shared<Euribor6M>();
    for (const Quoted& q : quotes) {
        if (q.kind == ":ois")
            result.push_back(ext::make_shared<OISRateHelper>(
                2, parsePeriod(q.tenor), Handle<Quote>(ext::make_shared<SimpleQuote>(q.quote)), on,
                Handle<YieldTermStructure>(), false, paymentLag, Following, Annual));
        else if (q.kind == ":deposit")
            result.push_back(ext::make_shared<DepositRateHelper>(
                Handle<Quote>(ext::make_shared<SimpleQuote>(q.quote)), euribor));
        else if (q.kind == ":fra")
            result.push_back(ext::make_shared<FraRateHelper>(
                Handle<Quote>(ext::make_shared<SimpleQuote>(q.quote)),
                Natural(std::stoi(q.tenor)), euribor));
        else
            result.push_back(ext::make_shared<SwapRateHelper>(
                Handle<Quote>(ext::make_shared<SimpleQuote>(q.quote)), parsePeriod(q.tenor),
                TARGET(), Annual, Unadjusted, Thirty360(Thirty360::BondBasis), euribor,
                Handle<Quote>(), 0 * Days, discount));
    }
    return result;
}

template <class Curve>
void print(FILE* out, const char* name, const char* interpolation, const char* discountName,
           const std::vector<Quoted>& quotes, const std::vector<ext::shared_ptr<RateHelper> >& hs,
           const Curve& curve) {
    curve->discount(today + 1);   // bootstrap now, so the helpers see the curve
    std::fprintf(out, " (:name %s :interpolation %s :discount-curve %s\n  :helpers (\n", name,
                 interpolation, discountName);
    for (Size i = 0; i < hs.size(); ++i)
        std::fprintf(out, "   (%s \"%s\" %.17g \"%s\" %.17g)\n", quotes[i].kind.c_str(),
                     quotes[i].tenor.c_str(), quotes[i].quote, iso(hs[i]->pillarDate()).c_str(),
                     hs[i]->impliedQuote());
    std::fprintf(out, "  )\n  :discounts (\n");
    for (int k = 0; k < 50; ++k) {
        Date d = today + 3 + k * 233;
        std::fprintf(out, "   (\"%s\" %.17g)\n", iso(d).c_str(), curve->discount(d));
    }
    std::fprintf(out, "  ))\n");
}

}

int main(int argc, char** argv) {
    if (argc != 2) {
        std::fprintf(stderr, "usage: %s output.sexp\n", argv[0]);
        return 1;
    }
    Settings::instance().evaluationDate() = today;
    FILE* out = std::fopen(argv[1], "w");
    std::fprintf(out, ";;;; bootstrap.sexp --- generated by tests/fixtures/generate.sh from QuantLib %s\n",
                 QL_VERSION);

    std::vector<std::string> oisTenors = {"1W", "2W", "1M", "2M", "3M", "4M", "6M", "9M", "1Y",
                                          "18M", "2Y", "3Y", "4Y", "5Y", "7Y", "10Y", "12Y",
                                          "15Y", "20Y", "25Y", "30Y"};
    std::vector<double> sofr = {3.85, 3.84, 3.82, 3.79, 3.76, 3.72, 3.66, 3.57, 3.50, 3.38, 3.30,
                                3.24, 3.25, 3.28, 3.36, 3.48, 3.55, 3.62, 3.68, 3.66, 3.62};
    std::vector<double> estr = {1.93, 1.93, 1.92, 1.91, 1.90, 1.89, 1.88, 1.88, 1.89, 1.93, 1.98,
                                2.07, 2.15, 2.23, 2.37, 2.53, 2.61, 2.68, 2.70, 2.63, 2.55};
    std::vector<Quoted> sofrQuotes, estrQuotes;
    for (Size i = 0; i < oisTenors.size(); ++i) {
        sofrQuotes.push_back({":ois", oisTenors[i], sofr[i] / 100});
        estrQuotes.push_back({":ois", oisTenors[i], estr[i] / 100});
    }
    std::vector<Quoted> euriborQuotes = {
        {":deposit", "6M", 0.0210}, {":fra", "1", 0.0208}, {":fra", "2", 0.0206},
        {":fra", "3", 0.0205}, {":fra", "6", 0.0204}, {":fra", "9", 0.0206},
        {":fra", "12", 0.0210}, {":swap", "2Y", 0.0215}, {":swap", "3Y", 0.0222},
        {":swap", "4Y", 0.0230}, {":swap", "5Y", 0.0237}, {":swap", "6Y", 0.0243},
        {":swap", "7Y", 0.0249}, {":swap", "8Y", 0.0254}, {":swap", "9Y", 0.0258},
        {":swap", "10Y", 0.0262}, {":swap", "12Y", 0.0269}, {":swap", "15Y", 0.0276},
        {":swap", "20Y", 0.0279}, {":swap", "25Y", 0.0274}, {":swap", "30Y", 0.0268}};

    std::fprintf(out, "(:curves\n");
    auto sofrIndex = ext::make_shared<Sofr>();
    auto estrIndex = ext::make_shared<Estr>();
    {
        auto hs = helpers(sofrQuotes, sofrIndex, 2, {});
        auto curve = ext::make_shared<PiecewiseYieldCurve<Discount, LogLinear> >(today, hs, Actual365Fixed());
        curve->enableExtrapolation();
        print(out, ":sofr", ":log-linear", "nil", sofrQuotes, hs, curve);
    }
    {
        auto hs = helpers(sofrQuotes, sofrIndex, 2, {});
        auto curve = ext::make_shared<PiecewiseYieldCurve<ForwardRate, ConvexMonotone> >(today, hs, Actual365Fixed());
        curve->enableExtrapolation();
        print(out, ":sofr", ":monotone-convex", "nil", sofrQuotes, hs, curve);
    }
    for (bool convex : {false, true}) {
        auto estrHelpers = helpers(estrQuotes, estrIndex, 1, {});
        ext::shared_ptr<YieldTermStructure> estrCurve;
        if (convex)
            estrCurve = ext::make_shared<PiecewiseYieldCurve<ForwardRate, ConvexMonotone> >(
                today, estrHelpers, Actual365Fixed());
        else
            estrCurve = ext::make_shared<PiecewiseYieldCurve<Discount, LogLinear> >(
                today, estrHelpers, Actual365Fixed());
        estrCurve->enableExtrapolation();
        const char* interpolation = convex ? ":monotone-convex" : ":log-linear";
        print(out, ":estr", interpolation, "nil", estrQuotes, estrHelpers, estrCurve);
        Handle<YieldTermStructure> estrHandle(estrCurve);
        auto hs = helpers(euriborQuotes, estrIndex, 1, estrHandle);
        ext::shared_ptr<YieldTermStructure> curve;
        if (convex)
            curve = ext::make_shared<PiecewiseYieldCurve<ForwardRate, ConvexMonotone> >(today, hs, Actual365Fixed());
        else
            curve = ext::make_shared<PiecewiseYieldCurve<Discount, LogLinear> >(today, hs, Actual365Fixed());
        curve->enableExtrapolation();
        print(out, ":euribor-6m", interpolation, ":estr", euriborQuotes, hs, curve);
    }
    std::fprintf(out, ")\n");
    std::fclose(out);
    return 0;
}
